import{_ as r,o as a,c as e,ae as n}from"./chunks/framework.Dn7Y7LSn.js";const c=JSON.parse('{"title":"リアルタイム監視","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/real-time-monitoring.md","filePath":"ja/guide/real-time-monitoring.md"}'),o={name:"ja/guide/real-time-monitoring.md"};function i(d,t,l,s,g,h){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="リアルタイム監視" tabindex="-1">リアルタイム監視 <a class="header-anchor" href="#リアルタイム監視" aria-label="Permalink to &quot;リアルタイム監視&quot;">​</a></h1><p>Orchestraは全てのClaude Codeセッションをライブステータス更新で単一のダッシュボードから監視します。</p><h2 id="仕組み" tabindex="-1">仕組み <a class="header-anchor" href="#仕組み" aria-label="Permalink to &quot;仕組み&quot;">​</a></h2><p>Claude Code実行時、重要なタイミングでhookイベントが発火されます。OrchestraはこれらのイベントをHTTPで受信し、ダッシュボードをリアルタイムで更新します。</p><h2 id="セッションの状態" tabindex="-1">セッションの状態 <a class="header-anchor" href="#セッションの状態" aria-label="Permalink to &quot;セッションの状態&quot;">​</a></h2><p>各セッションカードは現在の状態を表示します:</p><table tabindex="0"><thead><tr><th>ステータス</th><th>意味</th></tr></thead><tbody><tr><td><strong>Running</strong></td><td>Claudeがアクティブに作業中（読み取り、書き込み、実行）</td></tr><tr><td><strong>Thinking</strong></td><td>ツール呼び出しの間にClaudeが処理中</td></tr><tr><td><strong>Waiting Input</strong></td><td>Claudeが停止しユーザーの入力を待機中</td></tr><tr><td><strong>Waiting Permission</strong></td><td>続行するために権限が必要</td></tr><tr><td><strong>Done</strong></td><td>セッションが終了</td></tr></tbody></table><h2 id="アクティビティタイプ" tabindex="-1">アクティビティタイプ <a class="header-anchor" href="#アクティビティタイプ" aria-label="Permalink to &quot;アクティビティタイプ&quot;">​</a></h2><p>Claudeが現在何をしているかも表示されます:</p><ul><li><strong>Reading</strong> — ファイル読み取り（Read, Glob, Grepツール）</li><li><strong>Writing</strong> — ファイルの編集・作成（Edit, Writeツール）</li><li><strong>Running</strong> — コマンド実行（Bashツール）</li><li><strong>Coding</strong> — その他の開発ツール使用中</li><li><strong>Idle</strong> — アクティブなツール使用なし</li></ul><h2 id="セッションカード" tabindex="-1">セッションカード <a class="header-anchor" href="#セッションカード" aria-label="Permalink to &quot;セッションカード&quot;">​</a></h2><p>各セッションカードには以下が表示されます:</p><ul><li><strong>タイトル</strong> — 作業ディレクトリ名から自動取得</li><li><strong>ステータスバッジ</strong> — カラーコード付きの現在のセッション状態</li><li><strong>最終アクティビティ</strong> — 最新のツールやコマンド出力</li><li><strong>Jumpボタン</strong> — ターミナルセッションへのワンクリックナビゲーション</li></ul>',13)])])}const p=r(o,[["render",i]]);export{c as __pageData,p as default};
